harden_send_push_bad_sub.s:
Second root cause (same live diagnosis): src/lib/server/push.ts send_push (lines 189-219) `const body = await encrypt_payload(sub, payload);` runs BEFORE any try/catch. A stored subscription with a non-P-256 p256dh makes crypto.subtle.importKey throw `DataError: Failed to import raw EC key data: Invalid point encoding` (observed verbatim in `wrangler tail x2-ws` as `[RELAY] uid=... DO fetch THREW`); a malformed endpoint makes vapid_auth's `new URL(endpoint).origin` (push.ts:130) throw `TypeError: Invalid URL`. Either throw escapes send_push, rejects the hub's Promise.all fan-out, and kills every push for that user. Fix: send_push must never throw — a too-large plaintext is a MESSAGE problem (skip, don't prune) while bad sub keys / bad endpoint are a SUBSCRIPTION problem (report gone so callers prune).

Current code (src/lib/server/push.ts:189-219):
```ts
export async function send_push(
	sub: WebPushSub,
	payload: string,
	keys: PushKeys,
	opts: PushOpts = {},
	f: typeof fetch = fetch
): Promise<PushResult> {
	const body = await encrypt_payload(sub, payload);
	const headers: Record<string, string> = {
		'Content-Encoding': 'aes128gcm',
		'Content-Type': 'application/octet-stream',
		'Content-Length': String(body.byteLength),
		TTL: String(opts.ttl ?? 86400),
		Urgency: opts.urgency ?? 'high',
		Authorization: await vapid_auth(keys, sub.endpoint)
	};
	if (opts.topic) headers.Topic = opts.topic;

	const attempt = async (): Promise<Response | null> => {
		try {
			return await f(sub.endpoint, { method: 'POST', headers, body: bs(body) as BodyInit });
		} catch {
			return null;
		}
	};

	let res = await attempt();
	if (res && [429, 500, 503].includes(res.status)) res = await attempt();
	if (!res) return { ok: false, status: 0, gone: false };
	const gone = res.status === 404 || res.status === 410;
	return { ok: res.ok, status: res.status, gone };
}
```

Replacement (verbatim — hoist body/headers out of the try so attempt() can read them):
```ts
export async function send_push(
	sub: WebPushSub,
	payload: string,
	keys: PushKeys,
	opts: PushOpts = {},
	f: typeof fetch = fetch
): Promise<PushResult> {
	// plaintext-too-large is a message problem, not a subscription problem — skip the
	// sub rather than letting encrypt_payload's throw masquerade as a dead endpoint
	if (new TextEncoder().encode(payload).length > MAX_PLAINTEXT) {
		return { ok: false, status: 0, gone: false };
	}
	let body: Uint8Array;
	let headers: Record<string, string>;
	try {
		body = await encrypt_payload(sub, payload);
		headers = {
			'Content-Encoding': 'aes128gcm',
			'Content-Type': 'application/octet-stream',
			'Content-Length': String(body.byteLength),
			TTL: String(opts.ttl ?? 86400),
			Urgency: opts.urgency ?? 'high',
			Authorization: await vapid_auth(keys, sub.endpoint)
		};
		if (opts.topic) headers.Topic = opts.topic;
	} catch {
		// corrupt keys (non-P-256 p256dh, malformed auth) or a malformed endpoint URL —
		// the sub can never succeed; report gone so the caller prunes it
		return { ok: false, status: 0, gone: true };
	}

	const attempt = async (): Promise<Response | null> => {
		try {
			return await f(sub.endpoint, { method: 'POST', headers, body: bs(body) as BodyInit });
		} catch {
			return null;
		}
	};

	let res = await attempt();
	if (res && [429, 500, 503].includes(res.status)) res = await attempt();
	if (!res) return { ok: false, status: 0, gone: false };
	const gone = res.status === 404 || res.status === 410;
	return { ok: res.ok, status: res.status, gone };
}
```

Why: the pre-check runs BEFORE the size throw so a too-long message degrades to 'no push this round' (the unread count still increments; the recipient sees it in-app) instead of pruning every sub. Everything per-sub (encrypt, vapid) is wrapped so a bad sub yields gone:true (pruned by the caller) and never propagates.

